const item = $input.first();
const body = (item.json.snippet || item.json.textPlain || '').replace(/<[^>]*>/g, '');
const fromRaw = item.json.from || '';

const emailMatch = fromRaw.match(/<(.+?)>/);
const customerEmail = emailMatch ? emailMatch[1] : fromRaw.trim();

const nameMatch = body.match(/(?:I am|my name is|hello[,\s]+(?:my name is)?|name\s*:?\s*)([A-Z][a-z]+(?:\s[A-Z][a-z]+)?)/i);
const productMatch = body.match(/(?:order|ordering|would like)\s+(?:\d+\s+)?(?:jar[s]? of |bottle[s]? of |kg of |g of )?([a-zA-Z][\w\s\-]{3,40}?)(?:\s*(?:\d|\n|,|\.|of|for|to|please|thanks))/i);
const qtyMatch = body.match(/(\d+)\s*(?:unit[s]?|piece[s]?|jar[s]?|bottle[s]?|kg|gram[s]?|item[s]?)/);
const addressMatch = body.match(/(?:address|deliver\s+to|delivery\s+address\s*:?\s*|ship\s+to)([\w\s,\-]{10,120})/i);

return [{
  json: {
    email_from: fromRaw,
    customer_email: customerEmail,
    email_subject: item.json.subject || '',
    email_received_at: item.json.date || new Date().toISOString(),
    email_id: item.json.id || '',
    customer_name: nameMatch ? nameMatch[1].trim() : null,
    product: productMatch ? productMatch[1].trim() : null,
    quantity: qtyMatch ? parseInt(qtyMatch[1]) : 1,
    shipping_address: addressMatch ? addressMatch[1].trim() : null,
    raw_body_preview: body.substring(0, 300)
  }
}];

