const orderData = $('Extract Order Fields').item.json;

// Read last order number from previous node output (Sheets last row)
const sheetsItems = $input.all();
let lastNum = 0;
if (sheetsItems.length > 0) {
  const rows = sheetsItems;
  for (const row of rows) {
    const numStr = row.json['Number'] || '';
    const match = numStr.match(/ML-\d{4}-(\d+)/);
    if (match) {
      const n = parseInt(match[1]);
      if (n > lastNum) lastNum = n;
    }
  }
}

const year = new Date().getFullYear();
const nextNum = lastNum + 1;
const orderNumber = `ML-${year}-${String(nextNum).padStart(4, '0')}`;

return [{
  json: {
    ...orderData,
    order_number: orderNumber
  }
}];

